let cache: { regular: Buffer; bold: Buffer; italic: Buffer } | null = null;

/** Polices TTF de facture, décodées une seule fois. */
export function invoiceFonts(): { regular: Buffer; bold: Buffer; italic: Buffer } {
  if (!cache) {
    cache = {
      regular: Buffer.from(NOTO_SANS_REGULAR_B64, "base64"),
      bold: Buffer.from(NOTO_SANS_BOLD_B64, "base64"),
      italic: Buffer.from(NOTO_SANS_ITALIC_B64, "base64"),
    };
  }
  return cache;
}
